CREATE TABLE IF NOT EXISTS publishers (
 id SERIAL PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', website TEXT, "contactEmail" TEXT NOT NULL DEFAULT '', "contactPhone" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS authors (
 id SERIAL PRIMARY KEY, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "dateOfBirth" DATE, nationality TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', "photoUrl" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS membership_plans (
 id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', price NUMERIC(12,2) NOT NULL CHECK(price >= 0), "billingTerm" TEXT NOT NULL CHECK("billingTerm" IN ('monthly','annual')), "borrowingLimit" INTEGER NOT NULL CHECK("borrowingLimit" > 0), "loanPeriodDays" INTEGER NOT NULL CHECK("loanPeriodDays" > 0), "fineRatePerDay" NUMERIC(12,2) NOT NULL CHECK("fineRatePerDay" >= 0), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS members (
 id SERIAL PRIMARY KEY, "memberNumber" TEXT NOT NULL UNIQUE, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL DEFAULT '', nationality TEXT NOT NULL DEFAULT '', "dateOfBirth" DATE, "photoUrl" TEXT, "membershipId" INTEGER NOT NULL REFERENCES membership_plans(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','expired')), "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE books ADD COLUMN IF NOT EXISTS genre TEXT NOT NULL DEFAULT '';
ALTER TABLE books ADD COLUMN IF NOT EXISTS language TEXT NOT NULL DEFAULT '';
ALTER TABLE books ADD COLUMN IF NOT EXISTS publisher_id INTEGER REFERENCES publishers(id);
ALTER TABLE books ADD COLUMN IF NOT EXISTS edition TEXT NOT NULL DEFAULT '';
ALTER TABLE books ADD COLUMN IF NOT EXISTS description TEXT NOT NULL DEFAULT '';
ALTER TABLE books ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE loans ADD COLUMN IF NOT EXISTS member_id INTEGER REFERENCES members(id);
ALTER TABLE fines ADD COLUMN IF NOT EXISTS member_id INTEGER REFERENCES members(id);
CREATE TABLE IF NOT EXISTS sessions (
 id UUID PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL
);
